import { Column, Grid, Row } from '@umami/react-zen';
import { WebsiteExpandedMenu } from '@/app/(main)/websites/[websiteId]/WebsiteExpandedMenu';
import { useMessages, useNavigation } from '@/components/hooks';
import { MobileMenuButton } from '@/components/input/MobileMenuButton';
import { MetricsExpandedTable } from '@/components/metrics/MetricsExpandedTable';

export function WebsiteExpandedView({
  websiteId,
  excludedIds = [],
  onClose,
}: {
  websiteId: string;
  excludedIds?: string[];
  onClose?: () => void;
}) {
  const { t, labels } = useMessages();
  const {
    query: { view },
  } = useNavigation();
  const title = view === 'fullPath' ? t(labels.url) : t(labels[view]);

  return (
    <Column height="100%" overflow="hidden" gap>
      <Row id="expanded-mobile-menu-button" display={{ base: 'flex', md: 'none' }}>
        <MobileMenuButton>
          {({ close }) => {
            return (
              <Column padding="3">
                <WebsiteExpandedMenu excludedIds={excludedIds} onItemClick={close} />
              </Column>
            );
          }}
        </MobileMenuButton>
      </Row>
      <Grid columns={{ base: '1fr', md: 'auto 1fr' }} gap="6" overflow="hidden">
        <Column
          id="metrics-expanded-menu"
          display={{ base: 'none', md: 'flex' }}
          width="240px"
          gap="6"
          border="right"
          paddingRight="3"
          overflow="auto"
        >
          <WebsiteExpandedMenu excludedIds={excludedIds} />
        </Column>
        <Column id="metrics-expanded-table" overflow="hidden">
          <MetricsExpandedTable title={title} type={view} websiteId={websiteId} onClose={onClose} />
        </Column>
      </Grid>
    </Column>
  );
}

import { NavMenu } from '@/components/common/NavMenu';
import { useMessages, useNavigation } from '@/components/hooks';
import {
  AppWindow,
  Cpu,
  Earth,
  Fingerprint,
  Globe,
  KeyRound,
  Landmark,
  Languages,
  Laptop,
  Layers,
  Link2,
  LogIn,
  LogOut,
  MapPin,
  Megaphone,
  Monitor,
  Network,
  Search,
  Send,
  Share2,
  SquareSlash,
  Tag,
  Target,
  Type,
  Waypoints,
} from '@/components/icons';
import { Lightning } from '@/components/svg';

export function WebsiteExpandedMenu({
  excludedIds = [],
  onItemClick,
}: {
  excludedIds?: string[];
  onItemClick?: () => void;
}) {
  const { t, labels } = useMessages();
  const {
    updateParams,
    query: { view },
  } = useNavigation();

  const filterExcluded = (item: { id: string }) => !excludedIds.includes(item.id);

  const items = [
    {
      label: t(labels.pages),
      items: [
        {
          id: 'path',
          label: t(labels.path),
          path: updateParams({ view: 'path' }),
          icon: <SquareSlash />,
        },
        {
          id: 'fullPath',
          label: t(labels.url),
          path: updateParams({ view: 'fullPath' }),
          icon: <Waypoints />,
        },
        {
          id: 'entry',
          label: t(labels.entry),
          path: updateParams({ view: 'entry' }),
          icon: <LogIn />,
        },
        {
          id: 'exit',
          label: t(labels.exit),
          path: updateParams({ view: 'exit' }),
          icon: <LogOut />,
        },
        {
          id: 'title',
          label: t(labels.title),
          path: updateParams({ view: 'title' }),
          icon: <Type />,
        },
        {
          id: 'query',
          label: t(labels.query),
          path: updateParams({ view: 'query' }),
          icon: <Search />,
        },
      ].filter(filterExcluded),
    },
    {
      label: t(labels.sources),
      items: [
        {
          id: 'referrer',
          label: t(labels.referrer),
          path: updateParams({ view: 'referrer' }),
          icon: <Share2 />,
        },
        {
          id: 'channel',
          label: t(labels.channel),
          path: updateParams({ view: 'channel' }),
          icon: <Megaphone />,
        },
        {
          id: 'domain',
          label: t(labels.domain),
          path: updateParams({ view: 'domain' }),
          icon: <Globe />,
        },
      ].filter(filterExcluded),
    },
    {
      label: t(labels.location),
      items: [
        {
          id: 'country',
          label: t(labels.country),
          path: updateParams({ view: 'country' }),
          icon: <Earth />,
        },
        {
          id: 'region',
          label: t(labels.region),
          path: updateParams({ view: 'region' }),
          icon: <MapPin />,
        },
        {
          id: 'city',
          label: t(labels.city),
          path: updateParams({ view: 'city' }),
          icon: <Landmark />,
        },
      ].filter(filterExcluded),
    },
    {
      label: t(labels.environment),
      items: [
        {
          id: 'browser',
          label: t(labels.browser),
          path: updateParams({ view: 'browser' }),
          icon: <AppWindow />,
        },
        {
          id: 'os',
          label: t(labels.os),
          path: updateParams({ view: 'os' }),
          icon: <Cpu />,
        },
        {
          id: 'device',
          label: t(labels.device),
          path: updateParams({ view: 'device' }),
          icon: <Laptop />,
        },
        {
          id: 'language',
          label: t(labels.language),
          path: updateParams({ view: 'language' }),
          icon: <Languages />,
        },
        {
          id: 'screen',
          label: t(labels.screen),
          path: updateParams({ view: 'screen' }),
          icon: <Monitor />,
        },
      ].filter(filterExcluded),
    },
    {
      label: t(labels.utm),
      items: [
        {
          id: 'utmSource',
          label: t(labels.source),
          path: updateParams({ view: 'utmSource' }),
          icon: <Link2 />,
        },
        {
          id: 'utmMedium',
          label: t(labels.medium),
          path: updateParams({ view: 'utmMedium' }),
          icon: <Send />,
        },
        {
          id: 'utmCampaign',
          label: t(labels.campaign),
          path: updateParams({ view: 'utmCampaign' }),
          icon: <Target />,
        },
        {
          id: 'utmContent',
          label: t(labels.content),
          path: updateParams({ view: 'utmContent' }),
          icon: <Layers />,
        },
        {
          id: 'utmTerm',
          label: t(labels.term),
          path: updateParams({ view: 'utmTerm' }),
          icon: <KeyRound />,
        },
      ].filter(filterExcluded),
    },
    {
      label: t(labels.other),
      items: [
        {
          id: 'event',
          label: t(labels.event),
          path: updateParams({ view: 'event' }),
          icon: <Lightning />,
        },
        {
          id: 'hostname',
          label: t(labels.hostname),
          path: updateParams({ view: 'hostname' }),
          icon: <Network />,
        },
        {
          id: 'distinctId',
          label: t(labels.distinctId),
          path: updateParams({ view: 'distinctId' }),
          icon: <Fingerprint />,
        },
        {
          id: 'tag',
          label: t(labels.tag),
          path: updateParams({ view: 'tag' }),
          icon: <Tag />,
        },
      ].filter(filterExcluded),
    },
  ];

  return <NavMenu items={items} selectedKey={view} onItemClick={onItemClick} />;
}

